  "book.max-20.title": "Rauch und Salz",
  "book.mks-02.title": "Der Sumpf der schlechten Ideen",
  "book.mks-03.title": "Etwas fehlt",
  "book.mks-04.title": "Dem Labyrinth ist dein Plan egal",
  "book.mks-05.title": "Der Greif, der nicht fliegen wollte",
  "book.mks-06.title": "Der Übungsritter geht nachts um",
  "book.mks-07.title": "Etwas im See",
  "book.mks-08.title": "Der Ritter, der Wache hielt",
  "book.mks-09.title": "Fass nichts an, ohne zu fragen",
  "book.mks-10.title": "Worauf die Schule gebaut wurde",
  "book.mks-11.title": "Die Glocke, die um Mitternacht läutete",
  "book.mks-12.title": "Der Dieb mit den schwarzen Federn",
  "book.mks-13.title": "Die Seherin vom Michaelismarkt",
