  "soon.mks-21.title": "Die Flut, die zu spät kam",
  "soon.mks-22.title": "Die Boote, die heimkehrten",
  "soon.mks-23.title": "Anteile am Meer",
  "soon.mks-24.title": "Was jeder weiß",
  "soon.mks-25.title": "Das Wrack der Petrel",
  "soon.mks-26.title": "Die Mauer, die niemand brauchte",
  "soon.mks-27.title": "Die Regatta von Gullsmouth",
  "soon.mks-28.title": "Noch ein Korb",
